    fn drop_capacity<E>(
        &self,
        reserve: &mut impl FnMut(usize) -> Result<(), E>,
    ) -> Result<usize, E>;
    fn drain_types(&mut self, dispose: &mut impl FnMut(ResolvedType));
    fn clone_bytes(&self) -> Option<usize>;
