pub struct NominalPayload<T: NominalElement> {
    storage: Storage<T>,
}
#[derive(Debug, Eq, PartialEq)]
pub enum NominalMutationError<E> {
    Reservation(E),
    Capacity,
}
enum Storage<T: NominalElement> {
    Owned(Vec<T>),
    Shared(Arc<Owner<T>>),
}
impl<T: NominalElement> NominalPayload<T> {
    pub fn as_slice(&self) -> &[T] {
