}
impl<T: NominalElement> Clone for NominalPayload<T> {
    fn clone(&self) -> Self {
        match &self.storage {
            Storage::Owned(v) => v.clone().into(),
            Storage::Shared(v) => Self {
                storage: Storage::Shared(v.clone()),
            },
        }
    }
}
impl<T: NominalElement> Deref for NominalPayload<T> {
    type Target = Vec<T>;
