    }
}
impl<'a, T: NominalElement> IntoIterator for &'a NominalPayload<T> {
    type Item = &'a T;
    type IntoIter = std::slice::Iter<'a, T>;
    fn into_iter(self) -> Self::IntoIter {
        self.iter()
    }
}
impl<'a, T: NominalElement> IntoIterator for &'a mut NominalPayload<T> {
    type Item = &'a mut T;
